def is_inside(path: str) -> bool:
    """True when path stays inside its base directory: not absolute, and never climbs above its start through '..'."""
    ex is_inside("a.txt") == True
    ex is_inside("sub/../a.txt") == True
    ex is_inside("../x") == False
    ex is_inside("sub/../../x") == False
    ex is_inside("/etc/passwd") == False
    if path.startswith("/"):
        return False
    depth = 0
    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return True

def read_public(path: str) -> str uses fs:
    """Text of the file at path inside the directory notes, or an empty string when the path leaves notes or the file is missing or unreadable."""
    pre path.byte_len() >= 0
    post is_inside(path) or out == ""
    if not is_inside(path):
        return ""
    with fs = fs.sub("notes"):
        text = fs.read_text(path) else ""
    return text
